#!/usr/bin/env bash
# xatodo → superlive v2 component package build script (connect form).
#
# Output: dist/xatodo-connect-<version>-<platform>.zip
# Package structure (package root):
#   manifest.json          component manifest (generated by gen-manifest.py;
#                          files excludes itself; config declaration from
#                          scripts/connect-config.json — the connector needs
#                          backend.endpoint/backend.apikey configured before it
#                          can serve, the shell gates on those required fields)
#   config.toml            connect-form config ([backend] placeholders — the
#                          user edits them after import to point at their own
#                          running daemon)
#   config/{en,zh}.json    config field label i18n (referenced by the
#                          manifest config declaration)
#   bin/xa-todo-connect    connect-form server binary (unix executable bit
#                          kept; <bin>.exe on windows hosts)
#   ui/**                  full ui build artifact (the shell maps it to the
#                          /comps/{id}/ static space)
#
# Identity note: manifest id / namespace stay "xatodo" / "todo" — the same
# constants the component process self-reports via /health (connect reports
# the shared COMPONENT_ID constant, so a different manifest id would fail the
# shell's health cross-check). The two packages are therefore mutually
# exclusive forms of one logical component: the shell's namespace rule
# rejects installing connect alongside the standalone package ("namespace
# already taken"), and same-id install takes the replace path (config.toml
# is preserved). The display_name carries the form marker so the shell menu
# shows which form is installed.
#
# Contract references:
#   superlive/slsdk-rs/src/manifest.rs          manifest JSON shape and validate rules
#   superlive/shell/src-tauri/src/installer.rs  shell-side install checks
#                                               (fingerprints/set difference/unix perm restore)
#   superlive/docs/architecture.md              installation and lifecycle
#
# Usage: scripts/package-connect.sh (no args, one-shot: clean old artifacts
#        → full build (ui+server) → assemble → manifest → zip → self-verify;
#        node_modules must be installed beforehand — the script runs the ui
#        build through `npm run build` without installing dependencies)
#
# The script takes no platform argument: whatever platform it runs on is the
# platform it packages for (host build). The host rustc triple is mapped to
# a release-asset platform suffix (linux-x86_64 / macos-aarch64 /
# windows-x86_64, aligned with the superlive shell updater platform keys);
# an unknown triple fails the run instead of guessing.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
SERVER_DIR="$ROOT/server"   # cargo workspace root (entity/migration/server crates)
UI_DIR="$ROOT/ui"

COMPONENT_ID="xatodo"
NAMESPACE="todo"
DISPLAY_NAME="待办（转发）"
DISPLAY_NAME_EN="Todos (connector)"
BIN_NAME="xa-todo-connect"
MIN_SHELL_VERSION="0.1.0"
# Update declaration: the shell shows the update-check button for components
# declaring this; the URL serves the version manifest (generated by the
# release workflow as the connect-latest.json release asset).
UPDATE_MANIFEST_URL="https://github.com/drodreo/xatodo/releases/latest/download/connect-latest.json"

log() { echo "==> $*"; }
die() { echo "error: $*" >&2; exit 1; }

for tool in cargo rustc npm zip; do
  command -v "$tool" >/dev/null 2>&1 || die "missing required command: $tool"
done
PYTHON="$(command -v python3 || true)"
[ -n "$PYTHON" ] || PYTHON="$(command -v python || true)"
[ -n "$PYTHON" ] || die "missing required command: python3 (or python)"

# ---- Platform identity (host rustc triple → release asset platform suffix,
# naming aligned with the superlive shell updater platform keys) ----
HOST_TRIPLE="$(rustc -vV | awk '/^host:/{print $2}')"
case "$HOST_TRIPLE" in
  x86_64-unknown-linux-gnu)                     PLATFORM="linux-x86_64" ;;
  aarch64-apple-darwin)                         PLATFORM="macos-aarch64" ;;
  x86_64-pc-windows-msvc|x86_64-pc-windows-gnu) PLATFORM="windows-x86_64" ;;
  *) die "unsupported host triple: $HOST_TRIPLE (no platform mapping; add one explicitly)" ;;
esac
# Windows binaries carry the .exe suffix in target/release/, in the packaged
# bin name and in manifest launch.command (the shell spawns it verbatim).
BIN_EXT=""
case "$PLATFORM" in
  windows-*) BIN_EXT=".exe" ;;
esac
LAUNCH_COMMAND="./bin/${BIN_NAME}${BIN_EXT}"
log "Host platform: $HOST_TRIPLE → $PLATFORM"

# ---- 0. Clean old artifacts (one-shot semantics: every run starts from a
# clean artifact state) ----
log "Cleaning old artifacts: dist/xatodo-connect-*.zip + ui/dist"
rm -f "$ROOT/dist/xatodo-connect-"*.zip
rm -rf "$UI_DIR/dist"

# Identity same-source check: the manifest id must equal the runtime
# self-report (connect's /health reports the shared COMPONENT_ID constant)
# and the namespace must match the ui apiClient's NAMESPACE_PREFIX (the
# shell strips /api/{ns}/ before dispatching to the component).
SERVER_CID="$(sed -n 's|.*COMPONENT_ID: &str = "\([^"]*\)".*|\1|p' "$SERVER_DIR/integration/src/lib.rs" || true)"
if [ -z "$SERVER_CID" ]; then
  die "failed to extract the COMPONENT_ID constant from integration/src/lib.rs"
fi
if [ "$SERVER_CID" != "$COMPONENT_ID" ]; then
  die "COMPONENT_ID drift: script=$COMPONENT_ID server constant=$SERVER_CID"
fi
UI_NS_PREFIX="$(sed -n "s|.*NAMESPACE_PREFIX = '/api/\([^']*\)'.*|\1|p" "$UI_DIR/src/services/apiClient.ts" || true)"
if [ -z "$UI_NS_PREFIX" ]; then
  die "failed to extract NAMESPACE_PREFIX from ui/src/services/apiClient.ts"
fi
if [ "$UI_NS_PREFIX" != "$NAMESPACE" ]; then
  die "NAMESPACE drift: script=$NAMESPACE ui NAMESPACE_PREFIX=/api/$UI_NS_PREFIX"
fi

# ---- 1. Package version (source of truth: workspace
# [workspace.package].version) ----
VERSION="$(awk '/^\[workspace\.package\]/{sec=1; next} /^\[/{sec=0} sec && /^version = /{gsub(/"/, "", $3); print $3; exit}' "$SERVER_DIR/Cargo.toml")"
[ -n "$VERSION" ] || die "failed to extract version from [workspace.package] in $SERVER_DIR/Cargo.toml"
log "Package version: $VERSION"

STAGING="$(mktemp -d)"
trap 'rm -rf "$STAGING"' EXIT
mkdir -p "$ROOT/dist"
ZIP_PATH="$ROOT/dist/xatodo-connect-${VERSION}-${PLATFORM}.zip"

# ---- 2. server release build ----
log "Building server: cargo build --release -p xa-todo-connect"
(cd "$SERVER_DIR" && cargo build --release -p xa-todo-connect)
SERVER_BIN="$SERVER_DIR/target/release/${BIN_NAME}${BIN_EXT}"
[ -f "$SERVER_BIN" ] || die "release binary missing: $SERVER_BIN"

# ---- 3. ui build ----
log "Building ui: npm run build (artifact ui/dist)"
(cd "$UI_DIR" && npm run build)
# Component build form contract (ui/vite.config.js): the entry is the fixed
# name entry.js (rollupOptions.input is the sole src/entry.tsx +
# entryFileNames 'entry.js'), index.html is not part of the build artifact
[ -f "$UI_DIR/dist/entry.js" ] || die "ui build artifact incomplete: $UI_DIR/dist/entry.js missing"

# ---- 4. Assemble the package directory ----
log "Assembling package directory (bin + ui + config.toml)"
mkdir -p "$STAGING/bin" "$STAGING/ui"
cp "$SERVER_BIN" "$STAGING/bin/${BIN_NAME}${BIN_EXT}"
chmod 755 "$STAGING/bin/${BIN_NAME}${BIN_EXT}"
cp -a "$UI_DIR/dist/." "$STAGING/ui/"
cat > "$STAGING/config.toml" <<'EOF'
# xatodo connect-form config (bundled in the package; launched by the
# superlive v2 shell)
# The connect form is a pure forwarder: no local database, no users sync.
# After import, edit [backend] to point at your own running xatodo daemon
# (endpoint + one of its [users.entries] apikeys). The [server] and [users]
# placeholders are required by config deserialization but are not consumed
# by the connector.
[server]
listen = "0.0.0.0:8600"

# The daemon to front — the connector's required fields ship empty on
# purpose: an empty value counts as "missing" by the shell's config-gate
# convention, which routes a freshly installed connector to the config
# page before its first start (fill in endpoint + one of the daemon's
# [users.entries] apikeys there).
# use_system_proxy (optional, default false): false reaches the daemon
#   directly, ignoring ambient proxy settings (http_proxy env); set true
#   only when the network path to the daemon requires a proxy.
[backend]
endpoint = ""
apikey = ""
use_system_proxy = false

[users]
entries = []
EOF

# Config i18n label files: the manifest config declaration (woven in below)
# references config/{en,zh}.json — the shell resolves the field labels from
# these package-local files.
mkdir -p "$STAGING/config"
cat > "$STAGING/config/en.json" <<'EOF'
{
  "config.backend.endpoint.label": "Daemon address",
  "config.backend.apikey.label": "Daemon API key",
  "config.backend.use_system_proxy.label": "Reach the daemon through a proxy"
}
EOF
cat > "$STAGING/config/zh.json" <<'EOF'
{
  "config.backend.endpoint.label": "Daemon 地址",
  "config.backend.apikey.label": "Daemon API Key",
  "config.backend.use_system_proxy.label": "通过代理访问 Daemon"
}
EOF

# ---- 5. Generate manifest.json (entry discovery + full file fingerprints) ----
log "Generating manifest.json"
"$PYTHON" "$SCRIPT_DIR/gen-manifest.py" \
  --staging "$STAGING" \
  --id "$COMPONENT_ID" \
  --namespace "$NAMESPACE" \
  --display-name "$DISPLAY_NAME" \
  --display-name-en "$DISPLAY_NAME_EN" \
  --version "$VERSION" \
  --min-shell-version "$MIN_SHELL_VERSION" \
  --launch-command "$LAUNCH_COMMAND" \
  --config "$SCRIPT_DIR/connect-config.json" \
  --update-url "$UPDATE_MANIFEST_URL"

# ---- 6. zip packaging (relative paths + unix permissions) ----
log "Packaging: $ZIP_PATH"
rm -f "$ZIP_PATH"   # zip updates existing archives; delete first to avoid stale entries
(cd "$STAGING" && zip -qr "$ZIP_PATH" manifest.json config.toml config bin ui)

# ---- 7. Self-verification (simulates the shell-side install check chain) ----
log "Self-verifying the package (contract checks + set-difference consistency + fingerprint comparison)"
"$PYTHON" "$SCRIPT_DIR/verify-package.py" "$ZIP_PATH"

# ---- 8. ns prefix proof (generalization of the module-9 contract-misalignment
# defense) ----
# The UI sends /api/{ns}/{rest} (the shell strips the ns segment for
# dispatch); service paths in the artifact must carry this component's ns
# prefix — a missing segment becomes a runtime 404 inside the shell (the
# sl-finance incident showed systematic absence invisible to tsc/build; the
# only reliable interception point is a packaging-time grep of the artifact)
# The check accepts both service-path shapes: the full string "/api/todo/xxx"
# and the base constant "/api/todo" + template concatenation (the ns segment
# followed by a slash or a closing quote both match; the regex anchors on
# quote + ns segment + boundary, naturally avoiding false matches like
# /api/todoX). grep -c reads all input without early exit, eliminating the
# grep -q early-exit SIGPIPE misfire against unzip under pipefail (exit 141)
NS_HITS=$(unzip -p "$ZIP_PATH" ui/entry.js | grep -c -E "[\"']/api/todo(/|[\"'])" || true)
if [ "${NS_HITS:-0}" -gt 0 ]; then
  log "ns prefix proof: artifact contains /api/todo paths (${NS_HITS} hits) ✓"
else
  die "ns prefix missing: artifact ui/entry.js has no /api/todo paths (guaranteed 404 inside the shell)"
fi

# ---- 9. config declaration proof ----
# The connector is unusable without backend.endpoint/apikey — the shell gates
# on manifest-declared required fields and renders the config page from the
# declaration. A connect package with config: null ships an empty config page
# (nowhere to enter the daemon), which is exactly the 0.1.0 defect.
CONFIG_KEYS=$(unzip -p "$ZIP_PATH" manifest.json | "$PYTHON" -c '
import json, sys
m = json.load(sys.stdin)
cfg = m.get("config") or {}
keys = sorted(f["key"] for f in cfg.get("fields", []) if f.get("required"))
print("\n".join(keys))
')
for want in backend.endpoint backend.apikey; do
  case "$CONFIG_KEYS" in
    *"$want"*) ;;
    *) die "config declaration missing required field: $want (the shell cannot gate or render the daemon settings)" ;;
  esac
done
I18N_FILES=$(unzip -l "$ZIP_PATH" | grep -c "config/en.json\|config/zh.json" || true)
[ "${I18N_FILES:-0}" -eq 2 ] || die "config i18n files missing in package (need config/en.json + config/zh.json)"
log "config declaration proof: required fields backend.endpoint + backend.apikey declared, label i18n shipped ✓"

log "Packaging complete: $ZIP_PATH"
